 private function complete(array $j,array $r):array{$j['status']=$r['status'];if(isset($r['usage'])&&is_array($r['usage'])){$usage=[];foreach(['input_tokens','output_tokens','total_tokens','prompt_tokens','completion_tokens'] as $key)if(isset($r['usage'][$key])&&is_int($r['usage'][$key])&&$r['usage'][$key]>=0&&$r['usage'][$key]<=9007199254740991)$usage[$key]=$r['usage'][$key];if($usage)$j['usage']=$usage;}if(isset($r['handle']))$j['handle']=$r['handle'];if($j['status']==='completed'){if($j['task']==='image'){$label=Localization::t($j['sourceLocale']??'tr','aiIllustration');$j['result']=['cover'=>AIMedia::store($r['imageBase64']??'',$label,$label)];$j['previewUrl']=Config::basePath($this->config).'/api/admin/ai/media?id='.$j['result']['cover']['assetId'];}else $j['result']=AIContent::parse($j['task'],$r['text']??'',$j['context']);if(isset($j['cost']))$j['cost']=AIBudget::settle($j['cost'],$j['usage']??[],$j['task']);$j['warnings']=array_merge($j['result']['warnings']??[],['AI taslağını kaynaklarla karşılaştırın; uygulama normal editör kaydı gerektirir.']);}return $j;}
