   if($action==='cancel'){Validation::check($j['status']==='pending','Only jobs not yet submitted can be cancelled.');$j['status']='cancelled';$j['cost']['reserved']=0.;$j['cost']['estimated']=0.;$this->save($j);return $this->publicJob($j);}
